(function(api){
var bs=[], dust=[];
function num(k,d){ var p=api.params||{}; return p[k]!=null?+p[k]:d; }
function frame(dt){
  var W=api.width,H=api.height; if(!W||!H) return;
  var f=dt/16.6;
  var ctx=api.ctx;
  ctx.clearRect(0,0,W,H);
  var amt=num('bubbles',5), sz=(num('size',100))/100, spd=(num('speed',100))/100, du=num('dust',2);
  if(amt>0){
    var n=Math.floor(amt*8);
    while(bs.length<n){ bs.push({x:api.rand(0,W), y:api.rand(H*0.2,H), r:api.rand(2.5,9)*sz, vy:api.rand(0.5,1.8)*spd, ph:api.rand(0,6.28), wob:api.rand(0.4,1.2)}); }
    if(bs.length>n+30) bs.length=n+30;
    for(var i=0;i<bs.length;i++){
      var b=bs[i];
      b.y-=b.vy*f*0.8;
      b.x+=Math.sin(api.now()*0.001*b.wob+b.ph)*0.3*f;
      if(b.y<-b.r){ b.y=H+b.r; b.x=api.rand(0,W); }
      ctx.beginPath();
      ctx.arc(b.x,b.y,b.r,0,6.2832);
      ctx.strokeStyle='rgba(255,255,255,0.55)';
      ctx.lineWidth=Math.max(0.6,b.r*0.18);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(b.x-b.r*0.3,b.y-b.r*0.3,b.r*0.28,0,6.2832);
      ctx.fillStyle='rgba(255,255,255,0.8)';
      ctx.fill();
    }
  }
  if(du>0){
    var nd=Math.floor(du*14);
    while(dust.length<nd){ dust.push({x:api.rand(0,W), y:api.rand(0,H), r:api.rand(0.6,1.8), vy:api.rand(-0.15,0.05), vx:api.rand(-0.1,0.1)}); }
    if(dust.length>nd+30) dust.length=nd+30;
    ctx.fillStyle='rgba(255,255,255,0.5)';
    for(var j=0;j<dust.length;j++){
      var p2=dust[j];
      p2.x+=p2.vx*f; p2.y+=p2.vy*f;
      if(p2.y<-2)p2.y=H+2; if(p2.y>H+2)p2.y=-2;
      if(p2.x<-2)p2.x=W+2; if(p2.x>W+2)p2.x=-2;
      ctx.beginPath(); ctx.arc(p2.x,p2.y,p2.r,0,6.2832); ctx.fill();
    }
  }
}
function clear(){ try{ api.ctx.clearRect(0,0,api.width,api.height); }catch(e){} bs=[]; dust=[]; }
return { frame:frame, clear:clear, resize:clear };
})
